const db = require('../config/db');

/**
 * Controlador para la gestión y envío de notificaciones bidireccionales y persistidas.
 */
class NotificacionesController {

  /**
   * Obtiene la lista de notificaciones recibidas por el usuario autenticado
   */
  async getMisNotificaciones(req, res, next) {
    try {
      const id_usuario = req.user.id_usuario;
      const id_tipousuario = req.user.id_tipousuario;

      const list = await db('notificaciones as n')
        .leftJoin('notificaciones_lecturas as nl', function() {
          this.on('n.id_notificacion', '=', 'nl.id_notificacion')
              .andOn('nl.id_usuario', '=', db.raw('?', [id_usuario]));
        })
        .leftJoin('usuarios as u', 'n.id_remitente', 'u.id_usuario')
        .where(function() {
          this.where('n.id_usuario_destino', id_usuario)
              .orWhere('n.id_tipousuario_destino', id_tipousuario);
        })
        .select(
          'n.*',
          'u.nombre as remitente_nombre',
          'u.apellido_pat as remitente_apellido_pat',
          db.raw('ISNULL(nl.leido, 0) as leido'),
          'nl.fecha_leido'
        )
        .orderBy('n.fecha_alta', 'desc');

      res.json(list);
    } catch (err) {
      next(err);
    }
  }

  /**
   * Marca una notificación como leída por parte del usuario autenticado
   */
  async marcarLeida(req, res, next) {
    try {
      const id_usuario = req.user.id_usuario;
      const { id_notificacion } = req.body;

      if (!id_notificacion) {
        return res.status(400).json({ error: 'ID de notificación requerido.' });
      }

      // Verificar existencia de la notificación
      const notif = await db('notificaciones').where({ id_notificacion }).first();
      if (!notif) {
        return res.status(404).json({ error: 'Notificación no encontrada.' });
      }

      // Buscar si ya tiene un registro de lectura
      const lectura = await db('notificaciones_lecturas')
        .where({ id_notificacion, id_usuario })
        .first();

      if (lectura) {
        // Actualizar
        await db('notificaciones_lecturas')
          .where({ id_notificacion, id_usuario })
          .update({
            leido: 1,
            fecha_leido: db.fn.now()
          });
      } else {
        // Insertar
        await db('notificaciones_lecturas').insert({
          id_notificacion,
          id_usuario,
          leido: 1,
          fecha_leido: db.fn.now()
        });
      }

      res.json({ exito: true });
    } catch (err) {
      next(err);
    }
  }

  /**
   * Crea y envía una nueva notificación en la BD e inicia el aviso por sockets
   */
  async crearNotificacion(req, res, next) {
    try {
      const id_remitente = req.user.id_usuario;
      const { id_tipousuario_destino, id_usuario_destino, tipo, asunto, mensaje } = req.body;

      if (!asunto || !mensaje || !tipo) {
        return res.status(400).json({ error: 'Asunto, mensaje y tipo de notificación son obligatorios.' });
      }

      // Validar destino: o por rol o por usuario específico, no ambos ni ninguno
      if ((id_tipousuario_destino && id_usuario_destino) || (!id_tipousuario_destino && !id_usuario_destino)) {
        return res.status(400).json({
          error: 'Debes definir un destino exclusivo: ya sea por Rol (broadcast) o por Usuario específico, no ambos.'
        });
      }

      let tipoNum = 1;
      if (typeof tipo === 'number') {
        tipoNum = tipo;
      } else if (tipo === 'WARN' || tipo === 'advertencia' || tipo === 'observado') {
        tipoNum = 2;
      } else if (tipo === 'DANGER' || tipo === 'urgente' || tipo === 'rechazado') {
        tipoNum = 3;
      } else {
        tipoNum = 1; // INFO, SUCCESS, sistema, etc.
      }

      let insertedId;

      await db.transaction(async (trx) => {
        // 1. Guardar en BD (persistencia obligatoria usando raw OUTPUT para MSSQL)
        const result = await trx.raw(
          `INSERT INTO [notificaciones] ([id_remitente], [id_tipousuario_destino], [id_usuario_destino], [tipo], [asunto], [mensaje], [status])
           OUTPUT INSERTED.[id_notificacion]
           VALUES (?, ?, ?, ?, ?, ?, 1)`,
          [
            id_remitente,
            id_tipousuario_destino || null,
            id_usuario_destino || null,
            tipoNum,
            asunto,
            mensaje
          ]
        );

        insertedId = result[0]?.id_notificacion;

        // 2. Si es para un usuario específico, pre-poblar el registro de lectura en 0
        if (id_usuario_destino) {
          await trx('notificaciones_lecturas').insert({
            id_notificacion: insertedId,
            id_usuario: id_usuario_destino,
            leido: 0
          });
        }
      });

      // Obtener notificación con datos del remitente
      const notifCompleta = await db('notificaciones as n')
        .join('usuarios as u', 'n.id_remitente', 'u.id_usuario')
        .where('n.id_notificacion', insertedId)
        .select('n.*', 'u.nombre as remitente_nombre', 'u.apellido_pat as remitente_apellido_pat')
        .first();

      // 3. Emitir por Socket.io (aviso en vivo)
      const io = req.app.get('io');
      if (io) {
        if (id_usuario_destino) {
          io.to(`usuario_${id_usuario_destino}`).emit('notificacion_nueva', notifCompleta);
        } else if (id_tipousuario_destino) {
          const room = id_tipousuario_destino === 1 ? 'participantes' :
                       id_tipousuario_destino === 2 ? 'admins' :
                       id_tipousuario_destino === 3 ? 'jueces' : 'superadmins';
          io.to(room).emit('notificacion_nueva', notifCompleta);
        }
      }

      res.status(201).json({ exito: true, notificacion: notifCompleta });
    } catch (err) {
      next(err);
    }
  }
}

module.exports = new NotificacionesController();
